// UbigeoDistrito returns the entry for code and whether it is a known Distrito (INEI) code.
func UbigeoDistrito(code string) (UbigeoDistritoEntry, bool) {
	e, ok := ubigeoDistrito[code]
	return e, ok
}

// UbigeoDistritoValid reports whether code is a known Distrito (INEI) code.
func UbigeoDistritoValid(code string) bool {
	_, ok := ubigeoDistrito[code]
	return ok
}

// UbigeoDistritoProvincia returns the provincia of code, or "" if the code is unknown.
func UbigeoDistritoProvincia(code string) string {
	return ubigeoDistrito[code].Provincia
}
